SINA_SMART["hemato1-iron"] = {"lecture":"hemato1-iron","title":"Iron metabolism","mapStatus":"auto: generated by universal.py from the lecture summary and key points; not human-reviewed","los":[{"id":"hemato1-iron:e0","text":"Total body iron 4-5 g; no active excretion; regulated at absorption.","topic":"The big picture","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"hemato1-iron:e1","text":"Hb 60-75%; ferritin 10-20%; haemosiderin 5-10%; transferrin 0.1%.","topic":"Compartments","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"hemato1-iron:e2","text":"Diet 15-20 mg/day; ~10% (1-2 mg) absorbed = daily loss.","topic":"Compartments","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"hemato1-iron:e3","text":"Haem iron (Fe²⁺, meat) ~20% absorbed; non-haem (Fe³⁺, plants) 1-4%.","topic":"Absorption, transport and storage","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"hemato1-iron:e4","text":"Vitamin C increases, tannins decrease non-haem absorption.","topic":"Absorption, transport and storage","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"hemato1-iron:e5","text":"Absorption: duodenum; DcytB reduces, DMT1 imports.","topic":"Absorption, transport and storage","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"hemato1-iron:e6","text":"Ferroportin exports; hephaestin oxidises; transferrin carries 2 Fe³⁺.","topic":"Absorption, transport and storage","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"hemato1-iron:e7","text":"TfR1 on erythroid precursors; macrophages recycle iron.","topic":"Absorption, transport and storage","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"hemato1-iron:e8","text":"Hepcidin (liver) degrades ferroportin; ↑ in overload and inflammation.","topic":"Absorption, transport and storage","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"hemato1-iron:e9","text":"Ferritin: best marker of stores; Perls stain for marrow iron.","topic":"Laboratory assessment and disorders","sec":3,"importance":"core","highYield":"insufficient-source"}],"vmap":{},"mlevel":{"1eqw5xp":"a","8rymll":"a","u0e5vv":"a","udihxp":"a","1t40wld":"a","13tuksu":"a","z795i7":"a","bno64w":"a","14vwyfs":"a","4yblcf":"a","me5u0y":"a","1uy7wd2":"a","f1eq2o":"a"},"mapCounts":{"verified":0,"auto":13,"ambiguous":0,"missing":0},"mrules":[],"items":[],"experimental":[],"status":{},"difficulty":{},"expl":{"hemato1-iron:e0":{"s":0,"u":["Total body iron 4-5 g; no active excretion; regulated at absorption.","Total body iron is stable at 4-5 g (about 50 mg/kg in men, 40 in women).","The body cannot produce or actively excrete iron , so it is a nearly closed system regulated at the level of absorption : deficiency causes anaemia ; excess causes iron overload (haemochromatosis) ."],"dp":[]},"hemato1-iron:e1":{"s":1,"u":["Hb 60-75%; ferritin 10-20%; haemosiderin 5-10%; transferrin 0.1%.","Storage : ferritin 10-20% and haemosiderin 5-10% (liver, spleen, marrow).","Transport : transferrin about 0.1%."],"dp":[]},"hemato1-iron:e2":{"s":1,"u":["Diet 15-20 mg/day; ~10% (1-2 mg) absorbed = daily loss.","Daily balance: a diet of 15-20 mg , of which only about 10% (1-2 mg) is absorbed, matching 1-2 mg/day of physiological loss (skin and gut cells, menstruation)."],"dp":[]},"hemato1-iron:e3":{"s":2,"u":["Haem iron (Fe²⁺, meat) ~20% absorbed; non-haem (Fe³⁺, plants) 1-4%.","Haem iron (Fe²⁺, meat, liver, eggs) is well absorbed (about 20%): the whole haem enters the enterocyte and iron is freed from protoporphyrin.","Non-haem iron (Fe³⁺, vegetables, pulses, cereals) is poorly absorbed (1-4%): it is reduced to Fe²⁺ by duodenal cytochrome b (DcytB) and taken up by DMT1 ; vitamin C increases and tannins (tea) decrease its absorption."],"dp":[]},"hemato1-iron:e4":{"s":2,"u":["Vitamin C increases, tannins decrease non-haem absorption.","Non-haem iron (Fe³⁺, vegetables, pulses, cereals) is poorly absorbed (1-4%): it is reduced to Fe²⁺ by duodenal cytochrome b (DcytB) and taken up by DMT1 ; vitamin C increases and tannins (tea) decrease its absorption.","Haem iron (Fe²⁺, meat, liver, eggs) is well absorbed (about 20%): the whole haem enters the enterocyte and iron is freed from protoporphyrin."],"dp":[]},"hemato1-iron:e5":{"s":2,"u":["Absorption: duodenum; DcytB reduces, DMT1 imports.","Absorption occurs in the duodenum and proximal jejunum .","Non-haem iron (Fe³⁺, vegetables, pulses, cereals) is poorly absorbed (1-4%): it is reduced to Fe²⁺ by duodenal cytochrome b (DcytB) and taken up by DMT1 ; vitamin C increases and tannins (tea) decrease its absorption."],"dp":[]},"hemato1-iron:e6":{"s":2,"u":["Ferroportin exports; hephaestin oxidises; transferrin carries 2 Fe³⁺.","Export across the basolateral membrane uses ferroportin , the main point of regulation; hephaestin oxidises Fe²⁺ to Fe³⁺, which binds transferrin (made by the liver; 2 Fe³⁺ per molecule)."],"dp":[]},"hemato1-iron:e7":{"s":2,"u":["TfR1 on erythroid precursors; macrophages recycle iron.","Macrophages recycle iron from old red cells, supplying most plasma iron each day.","Cells take it up via transferrin receptor 1 (TfR1) , abundant on erythroid precursors; transferrin and receptor are recycled."],"dp":[]},"hemato1-iron:e8":{"s":2,"u":["Hepcidin (liver) degrades ferroportin; ↑ in overload and inflammation.","Hepcidin , made by the liver, binds and degrades ferroportin: it rises with iron excess and inflammation (lowering absorption and release) and falls in deficiency and increased erythropoiesis."],"dp":[]},"hemato1-iron:e9":{"s":3,"u":["Ferritin: best marker of stores; Perls stain for marrow iron.","Perls staining shows marrow iron.","Tests: serum iron , transferrin (total iron-binding capacity), transferrin saturation , and serum ferritin , the best marker of stores (low in deficiency; raised in overload but also in inflammation)."],"dp":[{"h":"Why chronic inflammation causes anaemia despite normal iron stores","t":"Inflammatory cytokines such as IL-6 make the liver produce more hepcidin. Hepcidin destroys ferroportin, so enterocytes stop releasing absorbed iron and macrophages keep the iron they recycle. Iron is locked in stores (ferritin normal or high) while the marrow is starved (low serum iron), producing the anaemia of chronic disease, a defence that deprives microbes of iron. Source: the lecture's regulation of iron metabolism."}]}},"meta":{"1eqw5xp":{"a":"recall","vg":"hemato1-iron:e0/recall/1"},"8rymll":{"a":"recall","vg":"hemato1-iron:e0/recall/2"},"u0e5vv":{"a":"recall","vg":"hemato1-iron:e2/recall/1"},"udihxp":{"a":"recall","vg":"hemato1-iron:e3/recall/1"},"1t40wld":{"a":"recall","vg":"hemato1-iron:e4/recall/1"},"13tuksu":{"a":"recall","vg":"hemato1-iron:e5/recall/1"},"z795i7":{"a":"recall","vg":"hemato1-iron:e5/recall/2"},"bno64w":{"a":"recall","vg":"hemato1-iron:e8/recall/1"},"14vwyfs":{"a":"recall","vg":"hemato1-iron:e6/recall/1"},"4yblcf":{"a":"recall","vg":"hemato1-iron:e8/recall/2"},"me5u0y":{"a":"recall","vg":"hemato1-iron:e8/recall/3"},"1uy7wd2":{"a":"recall","vg":"hemato1-iron:e9/recall/1"},"f1eq2o":{"a":"recall","vg":"hemato1-iron:e9/recall/2"}},"explRev":"549593b01bf3"};
